intentos.respuesta_cruda:
{
  "sql": "SELECT DISTINCT t.product_category_name_english, CAST(SUM(CASE WHEN r.review_score < avg_review_score THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(r.review_score) AS pct_mala_calificación FROM ( SELECT AVG(review_score) AS avg_review_score FROM vw_entregas_retrasos ) AS subq JOIN vw_entregas_retrasos r ON 1=1 JOIN order_items oi ON r.order_id = oi.order_id JOIN products p ON oi.product_id = p.product_id LEFT JOIN product_category_translation t ON p.product_category_name = t.product_category_name WHERE t.product_category_name_english IS NOT NULL GROUP BY t.product_category_name_english HAVING COUNT(r.review_score) >= 100 AND CAST(SUM(CASE WHEN r.entrega_con_retraso = 1 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(r.entrega_con_retraso) < ( SELECT CAST(SUM(CASE WHEN entrega_con_retraso = 1 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(entrega_con_retraso) FROM vw_entregas_retrasos WHERE entrega_con_retraso = 1 )"
}
